        if offset > len {
            return throw_index_size(ctx);
        }
        let actual_count = count.min(len - offset);
        let end = (offset.saturating_add(count)).min(len) as usize;
        units.drain(offset as usize..end);
        write_data_utf16(&this, &units, ctx);
