                            || c == '>'
                            || c == '}'
                            || c == '/'
                            || c == '\\'
                            || c.is_ascii_digit()
                            || c == '-'
                            || c == '.'
                            || c == ' '
                            || c == '^'
                            || c == '|'
                            || c == '&'
                            || c == '?'
                            || c == '*'
                            || c == '('
                            || c == ')'
                            || c == '+'
                            || c == '='
                            || c == '@'
                            || c == '$'
                            || c == '%'
                            || c == '#'
                            || c == '~'
                            || c == '!'
                            || c == '"'
                            || c == '\''
                            || c == '`'
