#[cfg(test)]
mod pending_family_landing_tests {
    //! The write-API family must LAND a createElement (pending)
    //! argument: before/after landed it (#90), replaceWith landed it
    //! (#92), but insertBefore/append/prepend still dropped it (L940
    //! pending family — fixed here).

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;
    use blitz_traits::NodeId;

    fn kid_tags(doc: &HtmlDocument, parent: &str) -> Vec<String> {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some(parent))
            .map(|(i, _)| {
                doc.get_node(i)
                    .map(|n| {
                        n.children
                            .iter()
                            .filter_map(|&c| doc.get_node(c))
                            .map(|cn| match cn.element_data() {
                                Some(el) => el.name.local.to_string(),
                                None => cn.text_content(),
                            })
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default()
            })
            .unwrap_or_default()
    }

    fn text_of(doc: &HtmlDocument, id: &str) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some(id))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    #[test]
    fn every_write_api_lands_a_pending_createelement_arg() {
        // insertBefore / before / after / append / prepend with a pending
        // createElement argument must all LAND it (insertBefore / append /
        // prepend dropped it until this fix — the L940 pending family).
        let cases: &[(&str, &str, &[&str])] = &[
            (
                "insertBefore",
                "list.insertBefore(made, first);",
                &["em", "li"],
            ),
            ("before", "first.before(made);", &["em", "li"]),
            ("after", "first.after(made);", &["li", "em"]),
            ("append", "list.append(made);", &["li", "em"]),
            ("prepend", "list.prepend(made);", &["em", "li"]),
        ];
        for (name, call, expected) in cases {
            let mut doc = HtmlDocument::from_html(
                r#"<html><body><ul id="list"><li id="first">a</li></ul></body></html>"#,
                DocumentConfig::default(),
            );
            let mut rt = JsRuntime::new();
            let script = format!(
                r#"
                var list = document.getElementById('list');
                var first = document.getElementById('first');
                var made = document.createElement('em');
                made.setText('M');
                {call}
                "#
            );
            rt.bind_and_run(&mut doc, &script);
            let tags = kid_tags(&doc, "list");
            assert_eq!(
                &tags, expected,
                "{name} must land the pending arg in DOM order"
            );
            assert!(
                text_of(&doc, "list").contains('M'),
                "{name} must carry the pending arg's text"
            );
        }
        let _ = NodeId::from_u64(0);
    }

    /// Move-not-clone across the family: the same createElement handle
    /// written through TWO different APIs must render exactly ONE element,
    /// in the LAST-write position. Round-2 S2: the append→insertBefore
    /// ordering is the ONLY one that discriminates a dropped first write
    /// (append lands the node regardless, masking an insertBefore drop), so
    /// this test uses append→insertBefore and asserts the first API's
    /// landing position in an intermediate window before the second write.
    #[test]
    fn pending_handle_across_two_apis_moves_not_clones() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><ul id="list"><li id="first">a</li><li id="b">b</li></ul></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        // Window 1: append lands the node at the TAIL.
        rt.bind_and_run(
            &mut doc,
            r#"
            var list = document.getElementById('list');
            var made = document.createElement('em');
            made.setText('M');
            list.append(made);
            "#,
        );
        assert_eq!(
            kid_tags(&doc, "list"),
            ["li", "li", "em"],
            "the first write (append) must land the node at the tail"
        );
        // Window 2: insertBefore(first) must MOVE it to the head — exactly
        // one <em>, not a clone.
        rt.bind_and_run(
            &mut doc,
            r#"
            var list = document.getElementById('list');
            var first = document.getElementById('first');
            list.insertBefore(made, first);
            "#,
        );
        assert_eq!(
            kid_tags(&doc, "list"),
            ["em", "li", "li"],
            "the second write (insertBefore) must MOVE the node to the head, not clone it"
        );
    }
}

#[cfg(test)]
mod pending_guard_order_tests {
    //! Round-5 S1: the pending arm originally materialized BEFORE the
    //! anchor-parent guard — `create_and_append` attaches as a side effect,
    //! so a guard-REJECTED insertBefore silently appended the node (tree
    //! mutated where pre-PR the op dropped cleanly). The three-phase
    //! restructure (guards → materialize → insert) restores the drop.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn kid_tags(doc: &HtmlDocument, parent: &str) -> Vec<String> {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some(parent))
            .map(|(i, _)| {
                doc.get_node(i)
                    .map(|n| {
                        n.children
                            .iter()
                            .filter_map(|&c| doc.get_node(c))
                            .map(|cn| match cn.element_data() {
                                Some(el) => el.name.local.to_string(),
                                None => cn.text_content(),
                            })
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default()
            })
            .unwrap_or_default()
    }

    /// Foreign anchor (lives under #other) + EMPTY parent: the op must be
    /// dropped — nothing may land in #list. Under the pre-fix ordering the
    /// node was appended first and left behind (["em"]).
    #[test]
    fn rejected_foreign_anchor_leaves_the_tree_untouched() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><ul id="list"></ul><div id="other"><span id="far">f</span></div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var list = document.getElementById('list');
            var far = document.getElementById('far');
            var made = document.createElement('em');
            made.setText('M');
            list.insertBefore(made, far);
            "#,
        );
        assert_eq!(
            kid_tags(&doc, "list"),
            Vec::<String>::new(),
            "a guard-rejected insertBefore must not mutate the tree"
        );
        assert_eq!(
            kid_tags(&doc, "other"),
            ["span"],
            "#other must be untouched"
        );
    }
}

#[cfg(test)]
mod parent_node_handle_tests {
    //! L940 (recorded across #85 R3 / #90 R9 / #93 R9): `parentNode` was a
    //! bare `{_arisId}` stub with no DOM method surface, so
    //! `el.parentNode.removeChild(el)` threw `TypeError: not a function`.
    //! The parent now resolves to a real element handle.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    #[test]
    fn parent_node_exposes_dom_methods() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="host"><span id="kid">k</span></div><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var kid = document.getElementById('kid');
            var pn = kid.parentNode;
            var report =
                'removeChild=' + (typeof pn.removeChild) +
                ' appendChild=' + (typeof pn.appendChild) +
                ' insertBefore=' + (typeof pn.insertBefore) +
                ' id=' + pn.id;
            document.getElementById('out').setText(report);
            "#,
        );
        let out = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default();
        assert_eq!(
            out, "removeChild=function appendChild=function insertBefore=function id=host",
            "parentNode must be a real handle: DOM methods present and id populated"
        );
    }

    /// The exact shape from L940 that used to throw.
    #[test]
    fn parent_node_remove_child_detaches_the_child() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="host"><span id="kid">k</span></div><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var kid = document.getElementById('kid');
            var ok = 'threw';
            try { kid.parentNode.removeChild(kid); ok = 'removed'; }
            catch (e) { ok = 'threw:' + e; }
            document.getElementById('out').setText(ok);
            "#,
        );
        let out = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default();
        assert_eq!(
            out, "removed",
            "el.parentNode.removeChild(el) must not throw (L940)"
        );
        // And the tree really dropped the child.
        let host_kids: Vec<String> = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("host"))
            .map(|(i, _)| {
                doc.get_node(i)
                    .map(|n| {
                        n.children
                            .iter()
                            .filter_map(|&c| doc.get_node(c))
                            .map(|cn| cn.text_content())
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default()
            })
            .unwrap_or_default();
        assert!(
            host_kids.is_empty(),
            "the child must leave the tree; got {host_kids:?}"
        );
    }
}

#[cfg(test)]
mod replace_child_op_tests {
    //! Round-5 S3 (PR #99): `replaceChild` was JS-mirror-only — it never
    //! pushed a bridge op, so the parsed tree was untouched and the call
    //! silently did nothing.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn kids(doc: &HtmlDocument, id: &str) -> Vec<String> {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some(id))
            .map(|(i, _)| {
                doc.get_node(i)
                    .map(|n| {
                        n.children
                            .iter()
                            .filter_map(|&c| doc.get_node(c))
                            .map(|cn| cn.text_content())
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default()
            })
            .unwrap_or_default()
    }

    fn text_of(doc: &HtmlDocument, id: &str) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some(id))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    /// A live node swapped in for another: the tree must show the NEW child
    /// and not the old one.
    #[test]
    fn live_replace_child_changes_the_tree() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="host"><span id="old">O</span></div><div id="spare">N</div><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var host = document.getElementById('host');
            var oldC = document.getElementById('old');
            var spare = document.getElementById('spare');
            var ret = host.replaceChild(spare, oldC);
            document.getElementById('out').setText('ret=' + ret.textContent);
            "#,
        );
        assert_eq!(
            kids(&doc, "host"),
            ["N"],
            "the tree must hold the NEW child (replaceChild used to be mirror-only)"
        );
        // DOM spec: replaceChild returns the OLD child (the replaced node).
        assert_eq!(
            text_of(&doc, "out"),
            "ret=O",
            "replaceChild returns the old child"
        );
    }

    /// A pending createElement argument named the #98 family contract: the
    /// replacement materializes instead of vanishing.
    #[test]
    fn pending_replace_child_materializes() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><ul id="host"><li id="old">O</li></ul><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var host = document.getElementById('host');
            var oldC = document.getElementById('old');
            var made = document.createElement('em');
            made.setText('M');
            host.replaceChild(made, oldC);
            "#,
        );
        assert_eq!(
            kids(&doc, "host"),
            ["M"],
            "a createElement argument must materialize in place of the old child"
        );
    }

    /// A replacement whose oldChild is NOT a child of this parent: no throw
    /// (see the S1 note in the arm — membership cannot be validated against
    /// the bind-time snapshot), and crucially NO tree damage.
    #[test]
    fn replacing_a_non_child_does_not_damage_either_tree() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="host"><span id="old">O</span></div><div id="other"><i id="far">F</i></div><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var host = document.getElementById('host');
            var far = document.getElementById('far');
            var made = document.createElement('em');
            made.setText('M');
            var r = 'no-throw';
            try { host.replaceChild(made, far); }
            catch (e) { r = 'threw'; }
            document.getElementById('out').setText(r);
            "#,
        );
        assert_eq!(
            text_of(&doc, "out"),
            "threw",
            "a non-child must be rejected (NotFoundError)"
        );
        assert_eq!(kids(&doc, "host"), ["O"], "#host must be untouched");
        assert_eq!(kids(&doc, "other"), ["F"], "#other must be untouched");
    }

    /// Round-5: the insert-side `_arisId` fallback IS observable — the
    /// mirror must place the inserted node BEFORE its anchor rather than
    /// appending it. Uses a LIVE node (a pending createElement carries
    /// `_arisId` 0, which makes the appended and inserted shapes identical
    /// and the test vacuous).
    #[test]
    fn insert_before_keeps_the_mirror_in_tree_order() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="host"><span id="b">B</span><span id="c">C</span></div><div id="free">F</div><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var host = document.getElementById('host');
            var b = document.getElementById('b');
            var free = document.getElementById('free');
            var bId = b._arisId, freeId = free._arisId;
            var cId = document.getElementById('c')._arisId;
            host.insertBefore(free, b);
            var seq = [];
            for (var i = 0; i < host._children.length; i++) {
                seq.push(host._children[i]._arisId);
            }
            // Report the mirror order as ids relative to b/free so the
            // assertion does not hard-code blitz slot numbers.
            document.getElementById('out').setText(
                seq.map(function (x) {
                    return x === bId ? 'b'
                         : x === freeId ? 'free'
                         : x === cId ? 'c'
                         : String(x);
                }).join(',')
            );
            "#,
        );
        assert_eq!(
            text_of(&doc, "out"),
            "free,b,c",
            "the mirror must show the inserted node BEFORE its anchor, not appended"
        );
    }

    /// Round-4 S1: the `_children` mirror is seeded with ANONYMOUS entries
    /// (only `_arisId`), so an identity-only removeChild silently no-opped —
    /// the mirror never shrank and the membership guard kept reading the
    /// stale set. The mirror must actually drop the child.
    #[test]
    fn remove_child_shrinks_the_children_mirror() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="host"><span id="a">A</span><span id="b">B</span></div><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var host = document.getElementById('host');
            var a = document.getElementById('a');
            var before = host._children.length;
            host.removeChild(a);
            var after = host._children.length;
            document.getElementById('out').setText('before=' + before + ' after=' + after);
            "#,
        );
        assert_eq!(
            text_of(&doc, "out"),
            "before=2 after=1",
            "removeChild must shrink the JS mirror, not silently no-op"
        );
        assert_eq!(
            kids(&doc, "host"),
            ["B"],
            "and the tree must drop the child"
        );
    }

    /// And the guard must therefore REJECT a node that the same window
    /// already removed (round-4 S1: it accepted it because the mirror still
    /// listed it).
    #[test]
    fn replace_child_rejects_a_node_removed_in_the_same_window() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="host"><span id="a">A</span></div><div id="spare">S</div><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var host = document.getElementById('host');
            var a = document.getElementById('a');
            var spare = document.getElementById('spare');
            host.removeChild(a);
            var r = 'no-throw';
            try { host.replaceChild(spare, a); } catch (e) { r = 'threw'; }
            document.getElementById('out').setText(r);
            "#,
        );
        assert_eq!(
            text_of(&doc, "out"),
            "threw",
            "a node removed in this window is no longer a child"
        );
    }

    /// Two replaceChild calls in ONE window (the swap-twice idiom) must both
    /// land — round-2 S1: the bind-time membership guard falsely threw on the
    /// second call and dropped the write.
    #[test]
    fn two_replace_child_calls_in_one_window_both_land() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="host"><span id="v1">V1</span></div><div id="s2">V2</div><div id="s3">V3</div><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var host = document.getElementById('host');
            var v1 = document.getElementById('v1');
            var v2 = document.getElementById('s2');
            var v3 = document.getElementById('s3');
            var r1 = 'ok1', r2 = 'ok2';
            try { host.replaceChild(v2, v1); } catch (e) { r1 = 'threw1'; }
            try { host.replaceChild(v3, v2); } catch (e) { r2 = 'threw2'; }
            document.getElementById('out').setText(r1 + '|' + r2);
            "#,
        );
        assert_eq!(
            text_of(&doc, "out"),
            "ok1|ok2",
            "the second replaceChild must not be rejected by a stale snapshot"
        );
        assert_eq!(
            kids(&doc, "host"),
            ["V3"],
            "both swaps must land; the tree ends with the last replacement"
        );
    }
}

#[cfg(test)]
mod next_sibling_tests {
    //! L940 (R5 of #99): `nextSibling`/`previousSibling` walked the parent's
    //! `_children` mirror matching by OBJECT IDENTITY, but the mirror is
    //! seeded with anonymous `{_arisId}` stubs — so both accessors returned
    //! null for every parsed element. They now fall back to `_arisId` and
    //! resolve the result into a real element handle.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    #[test]
    fn middle_siblings_resolve_both_ways() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><ul id="l"><li id="a">A</li><li id="b">B</li><li id="c">C</li></ul><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var a = document.getElementById('a');
            var b = document.getElementById('b');
            var c = document.getElementById('c');
            document.getElementById('out').setText([
                'a.next=' + (a.nextSibling && a.nextSibling.id),
                'b.prev=' + (b.previousSibling && b.previousSibling.id),
                'b.next=' + (b.nextSibling && b.nextSibling.id),
                'c.prev=' + (c.previousSibling && c.previousSibling.id),
            ].join(' '));
            "#,
        );
        assert_eq!(
            out_of(&doc),
            "a.next=b b.prev=a b.next=c c.prev=b",
            "both accessors must resolve the real neighbours"
        );
    }

    #[test]
    fn first_and_last_have_a_null_edge() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><ul id="l"><li id="a">A</li><li id="b">B</li></ul><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var a = document.getElementById('a');
            var b = document.getElementById('b');
            document.getElementById('out').setText(
                'firstPrev=' + (a.previousSibling === null) +
                ' lastNext=' + (b.nextSibling === null)
            );
            "#,
        );
        assert_eq!(
            out_of(&doc),
            "firstPrev=true lastNext=true",
            "the edges must be null, not undefined or a stub"
        );
    }

    /// The returned sibling must be a REAL handle (DOM methods + id), not the
    /// anonymous mirror stub — the same defect class as the `parentNode` bare
    /// stub fixed in #99.
    #[test]
    fn returned_sibling_is_a_real_handle() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><ul id="l"><li id="a">A</li><li id="b">B</li></ul><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var a = document.getElementById('a');
            var ns = a.nextSibling;
            document.getElementById('out').setText(
                'id=' + ns.id +
                ' tag=' + ns.tagName +
                ' hasMethods=' + (typeof ns.removeChild === 'function') +
                ' parentIsL=' + (ns.parentNode !== null && ns.parentNode.id === 'l')
            );
            "#,
        );
        assert_eq!(
            out_of(&doc),
            "id=b tag=LI hasMethods=true parentIsL=true",
            "the sibling must be a full handle, not an anonymous stub"
        );
    }
}

#[cfg(test)]
mod remove_child_membership_tests {
    //! L940 (R2 of #99): `add_dom_methods::removeChild` — the variant
    //! installed on objects built by that path (a `new Document()`, its body,
    //! a DocumentFragment) — had no membership check. `remove_from_children`
    //! is a silent no-op when the child is absent, and the function then
    //! returned the child as if it had been removed, so
    //! `parent.removeChild(unrelatedNode)` looked like success. DOM throws
    //! NotFoundError.
    //!
    //! NOTE the surface: ordinary `getElementById` handles go through
    //! make_element_handle's own removeChild (which already had the guard), so
    //! these tests deliberately use a `new Document()` body.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// A non-child on the add_dom_methods surface must throw.
    #[test]
    fn add_dom_methods_remove_child_rejects_a_non_child() {
        let out = run(r#"
            var d = new Document();
            var parent = d.createElement('div');
            var kid = d.createElement('span');
            var stranger = d.createElement('em');
            parent.appendChild(kid);
            var r = 'no-throw';
            try { parent.removeChild(stranger); } catch (e) { r = 'threw'; }
            document.getElementById('out').setText(r);
            "#);
        assert_eq!(out, "threw", "a non-child must be rejected on this surface");
    }

    /// And a real child still removes (the guard must not over-reject).
    #[test]
    fn add_dom_methods_remove_child_accepts_a_real_child() {
        let out = run(r#"
            var d = new Document();
            var parent = d.createElement('div');
            var kid = d.createElement('span');
            parent.appendChild(kid);
            var r = 'threw';
            try { parent.removeChild(kid); r = 'ok'; } catch (e) { r = 'threw'; }
            document.getElementById('out').setText(r);
            "#);
        assert_eq!(out, "ok", "a real child must still be removable");
    }
}

#[cfg(test)]
mod eventtarget_dedup_tests {
    //! WHATWG dedup on the EventTarget factory surface: re-adding the SAME
    //! callback on the same target+type is a no-op. Without it the duplicate
    //! stacked and fired twice, and one removeEventListener then dropped both
    //! (the element and document surfaces got this contract in #95/#96).

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// The reported shape: duplicate add stacks, fires twice, and ONE remove
    /// drops both.
    #[test]
    fn duplicate_add_is_a_noop_and_one_remove_clears_it() {
        let out = run(r#"
            var log = [];
            var t = new EventTarget();
            var h = function () { log.push('H'); };
            t.addEventListener('ping', h);
            t.addEventListener('ping', h);
            var dupLen = t._js_listeners.ping.length;
            t.dispatchEvent({ type: 'ping' });
            var fired = log.length;
            t.removeEventListener('ping', h);
            document.getElementById('out').setText(
                'dupLen=' + dupLen + ' fired=' + fired +
                ' rmLen=' + t._js_listeners.ping.length
            );
            "#);
        assert_eq!(
            out, "dupLen=1 fired=1 rmLen=0",
            "a duplicate add must collapse to one registration"
        );
    }

    /// Two DIFFERENT handlers must both register and both fire.
    #[test]
    fn distinct_handlers_both_register() {
        let out = run(r#"
            var log = [];
            var t = new EventTarget();
            t.addEventListener('ping', function () { log.push('A'); });
            t.addEventListener('ping', function () { log.push('B'); });
            t.dispatchEvent({ type: 'ping' });
            document.getElementById('out').setText(
                'len=' + t._js_listeners.ping.length + ' log=' + log.join('')
            );
            "#);
        assert_eq!(
            out, "len=2 log=AB",
            "distinct handlers must both register and fire in order"
        );
    }

    /// Removing one of two distinct handlers leaves the other live.
    #[test]
    fn removing_one_of_two_leaves_the_other() {
        let out = run(r#"
            var log = [];
            var t = new EventTarget();
            var a = function () { log.push('A'); };
            var b = function () { log.push('B'); };
            t.addEventListener('ping', a);
            t.addEventListener('ping', b);
            t.removeEventListener('ping', a);
            t.dispatchEvent({ type: 'ping' });
            document.getElementById('out').setText(
                'len=' + t._js_listeners.ping.length + ' log=' + log.join('')
            );
            "#);
        assert_eq!(out, "len=1 log=B", "the surviving handler must still fire");
    }
}

#[cfg(test)]
mod document_handle_event_tests {
    //! Round-2 F2 of PR #103: the document dispatchEvent unwrapped
    //! `{callback, passive}` and then required `callback` to be CALLABLE, with
    //! no `handleEvent` fallback. The element and EventTarget surfaces both
    //! support object listeners, so a document `handleEvent` listener was
    //! registered and never fired.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="out">init</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    #[test]
    fn document_handle_event_object_fires() {
        let out = run(r#"
            var obj = { handleEvent: function (e) { this.seen = (this.seen || 0) + 1; } };
            document.addEventListener('ping', obj);
            document.dispatchEvent({ type: 'ping' });
            document.dispatchEvent({ type: 'ping' });
            document.getElementById('out').setText('seen=' + (obj.seen || 0));
            "#);
        assert_eq!(
            out, "seen=2",
            "a document listener with handleEvent must fire on each dispatch"
        );
    }

    /// The plain-function path must keep working (no over-change).
    #[test]
    fn document_plain_function_still_fires() {
        let out = run(r#"
            var n = 0;
            document.addEventListener('ping', function () { n++; });
            document.dispatchEvent({ type: 'ping' });
            document.getElementById('out').setText('n=' + n);
            "#);
        assert_eq!(out, "n=1", "a plain function listener must still fire");
    }

    /// `this` inside handleEvent is the listener object per DOM.
    #[test]
    fn handle_event_this_is_the_listener_object() {
        let out = run(r#"
            var obj = {
                tag: 'MINE',
                handleEvent: function () { document.getElementById('out').setText('this=' + this.tag); }
            };
            document.addEventListener('ping', obj);
            document.dispatchEvent({ type: 'ping' });
            "#);
        assert_eq!(
            out, "this=MINE",
            "handleEvent must be invoked with the listener object as `this`"
        );
    }
}

#[cfg(test)]
mod stable_handle_identity_tests {
    //! L940 (PR #103 R3): `getElementById` built a FRESH handle object per
    //! call, so per-handle state was invisible to a later fetch —
    //! `getElementById('el').addEventListener(...)` then
    //! `getElementById('el').dispatchEvent(...)` registered and dispatched
    //! against different objects and never fired. `getElementById` handles are
    //! now cached per node id and re-populated on each access, so identity
    //! persists while SNAPSHOT-backed properties stay fresh.
    //!
    //! NOT covered (still fresh-per-call, listeners still invisible across
    //! fetches): `querySelector`, `getElementsByTagName`,
    //! `getElementsByClassName`, and `document.body`.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="el">E</div><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// The reported shape — and the THREE other add/dispatch combinations that
    /// all failed before the fix (only "same held variable" worked).
    #[test]
    fn every_add_dispatch_combination_fires() {
        let cases: &[(&str, &str, &str)] = &[
            (
                "fresh_add_fresh_dispatch",
                "document.getElementById('el').addEventListener('ping', function(){n++;});",
                "document.getElementById('el').dispatchEvent({type:'ping'});",
            ),
            (
                "held_add_fresh_dispatch",
                "var el = document.getElementById('el'); el.addEventListener('ping', function(){n++;});",
                "document.getElementById('el').dispatchEvent({type:'ping'});",
            ),
            (
                "fresh_add_held_dispatch",
                "document.getElementById('el').addEventListener('ping', function(){n++;});",
                "var el2 = document.getElementById('el'); el2.dispatchEvent({type:'ping'});",
            ),
            (
                "held_add_held_dispatch",
                "var el3 = document.getElementById('el'); el3.addEventListener('ping', function(){n++;});",
                "el3.dispatchEvent({type:'ping'});",
            ),
        ];
        for (name, add, disp) in cases {
            let out = run(&format!(
                "var n = 0; {add} {disp} document.getElementById('out').setText('n=' + n);"
            ));
            assert_eq!(out, "n=1", "{name} must fire exactly once");
        }
    }

    /// Identity must be stable across fetches.
    #[test]
    fn repeated_fetches_return_the_same_handle() {
        let out = run(r#"
            var a = document.getElementById('el');
            var b = document.getElementById('el');
            document.getElementById('out').setText('same=' + (a === b));
            "#);
        assert_eq!(out, "same=true", "two fetches must yield the same object");
    }

    /// ... while properties stay FRESH (the cache re-populates on each hit).
    #[test]
    fn cached_handle_properties_stay_fresh() {
        // Round-2 S3: asserting on a value the snapshot already holds passes
        // even with the re-populate disabled, so OVERWRITE a snapshot-backed
        // key on the handle first — only a real re-populate restores it.
        let out = run(r#"
            var h = document.getElementById('el');
            h.tagName = 'HACKED';
            h.nodeType = 99;
            var again = document.getElementById('el');
            document.getElementById('out').setText(
                'tag=' + again.tagName + ' nt=' + again.nodeType
            );
            "#);
        assert_eq!(
            out, "tag=DIV nt=1",
            "re-populate must restore snapshot-backed keys overwritten on the handle"
        );
    }

    /// A removed listener must not survive through the cache.
    #[test]
    fn remove_still_works_through_the_cache() {
        let out = run(r#"
            var n = 0;
            var fn = function () { n++; };
            document.getElementById('el').addEventListener('ping', fn);
            document.getElementById('el').dispatchEvent({type:'ping'});
            document.getElementById('el').removeEventListener('ping', fn);
            document.getElementById('el').dispatchEvent({type:'ping'});
            document.getElementById('out').setText('n=' + n);
            "#);
        assert_eq!(
            out, "n=1",
            "the removed listener must not fire on the second dispatch"
        );
    }
}

#[cfg(test)]
mod selector_handle_cache_tests {
    //! L940 (PR #104 R2): only `getElementById` was routed through the handle
    //! cache, so `querySelector` and the `getElementsBy*` lookups still minted
    //! a fresh handle per call and their listeners stayed invisible to a later
    //! fetch — the same defect class #104 fixed for one entry point.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="el" class="kel">E</div><span id="sp" class="ksp">S</span><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// `querySelector` and `getElementById` must yield the SAME object.
    #[test]
    fn query_selector_matches_get_element_by_id() {
        let out = run(r#"
            var a = document.getElementById('el');
            var b = document.querySelector('#el');
            document.getElementById('out').setText('same=' + (a === b));
            "#);
        assert_eq!(out, "same=true", "both lookups must return one handle");
    }

    /// A listener registered through `querySelector` must be visible to a
    /// dispatch through `getElementById` (and vice versa).
    #[test]
    fn query_selector_listener_survives_a_second_fetch() {
        let out = run(r#"
            var n = 0;
            document.querySelector('#el').addEventListener('ping', function(){ n++; });
            document.getElementById('el').dispatchEvent({ type: 'ping' });
            document.getElementById('out').setText('n=' + n);
            "#);
        assert_eq!(
            out, "n=1",
            "the listener must survive a different entry point"
        );
    }

    /// Same for `getElementsByClassName`.
    #[test]
    fn get_elements_by_class_name_shares_the_handle() {
        // Round-2 S2: register AND dispatch through the SAME by-class lookup,
        // so reverting the by-class call site to a fresh handle is caught
        // here (at af2fbe4 this test dispatched via getElementById and a
        // revert of the by-class site survived).
        let out = run(r#"
            var n = 0;
            var viaClass = document.getElementsByClassName('kel')[0];
            viaClass.addEventListener('ping', function(){ n++; });
            viaClass.dispatchEvent({ type: 'ping' });
            document.getElementById('el').dispatchEvent({ type: 'ping' });
            document.getElementById('out').setText('n=' + n);
            "#);
        assert_eq!(
            out, "n=2",
            "both dispatches must reach the one registration"
        );
    }

    /// Same for `getElementsByTagName`.
    #[test]
    fn get_elements_by_tag_name_shares_the_handle() {
        let out = run(r#"
            var n = 0;
            // Resolve the index by id so the test does not depend on
            // collection order (that ordering is a separate, pre-existing
            // concern); the point is that the SAME handle is returned.
            var list = document.getElementsByTagName('div');
            var target = null;
            for (var i = 0; i < list.length; i++) {
                if (list[i].id === 'el') target = list[i];
            }
            target.addEventListener('ping', function(){ n++; });
            document.getElementById('el').dispatchEvent({ type: 'ping' });
            document.getElementById('out').setText('n=' + n);
            "#);
        assert_eq!(out, "n=1", "the by-tag lookup must share the handle too");
    }

    /// The prototype must still be set on handles returned from the
    /// collection lookups (they used to call set_element_prototype).
    #[test]
    fn collection_lookups_still_carry_their_prototype() {
        // Resolve BY ID: the collection order is hash-based and not stable
        // across runs (round-2 S1-b of PR #105) — indexing [0] pins whatever
        // element the hash happens to yield, not the one this test names.
        let out = run(r#"
            var list = document.getElementsByClassName('kel');
            var el = null;
            for (var i = 0; i < list.length; i++) {
                if (list[i].id === 'el') el = list[i];
            }
            document.getElementById('out').setText(
                'found=' + (el !== null) +
                ' tag=' + (el && el.tagName) +
                ' id=' + (el && el.id)
            );
            "#);
        assert_eq!(
            out, "found=true tag=DIV id=el",
            "the collection handle for #el must be populated"
        );
    }
}

#[cfg(test)]
mod element_scoped_collections_tests {
    //! Round-5 S2 of PR #105: element-level `getElementsByTagName` /
    //! `getElementsByClassName` ignored `this` and returned whole-document
    //! matches. DOM scopes them to THIS element's descendants.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body>
            <div id="p"><span class="same">in-p</span><em id="in-p-em">e</em></div>
            <div id="q"><span class="same">in-q</span></div>
            <div id="out">i</div>
            </body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// `#p.getElementsByClassName("same")` must return ONLY the span inside
    /// #p — not the document-wide match set.
    #[test]
    fn element_class_collection_is_scoped_to_this() {
        let out = run(r#"
            var p = document.getElementById('p');
            var n = p.getElementsByClassName('same').length;
            document.getElementById('out').setText('n=' + n);
            "#);
        assert_eq!(out, "n=1", "only the descendant span must match");
    }

    /// `#p.getElementsByTagName("span")` — same scoping for the by-tag form.
    #[test]
    fn element_tag_collection_is_scoped_to_this() {
        let out = run(r#"
            var p = document.getElementById('p');
            var n = p.getElementsByTagName('span').length;
            document.getElementById('out').setText('n=' + n);
            "#);
        assert_eq!(out, "n=1", "only the descendant span must match");
    }

    /// The elements returned by the scoped lookup must be the RIGHT ones
    /// (the in-#p span, not the in-#q one).
    #[test]
    fn scoped_lookup_returns_the_right_elements() {
        let out = run(r#"
            var p = document.getElementById('p');
            var c = p.getElementsByClassName('same');
            var txt = '';
            for (var i = 0; i < c.length; i++) { txt += c[i].textContent; }
            document.getElementById('out').setText(txt);
            "#);
        assert_eq!(out, "in-p", "the scoped lookup must return the in-#p span");
    }
}

#[cfg(test)]
mod collection_order_tests {
    //! L940 (PR #105 R2): the collection lookups walked `node_props` (a
    //! HashMap) in HASH ORDER, so `getElementsByClassName(cls)[0]` differed
    //! across runs and was generally NOT the first match in document order.
    //! The `query_by_tag` / `query_by_class` indexes now store id LISTS built
    //! in TREE ORDER, and every collection read goes through them.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body>
            <div id="first" class="k">F</div>
            <div id="mid" class="k">M</div>
            <div id="last" class="k">L</div>
            <div id="out">i</div>
            </body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// `[0]` must be the FIRST element in DOCUMENT order, on repeated runs.
    #[test]
    fn by_class_index_zero_is_the_document_first() {
        let out = run(r#"
            var c = document.getElementsByClassName('k');
            document.getElementById('out').setText('n=' + c.length + ' first=' + c[0].id);
            "#);
        assert_eq!(
            out, "n=3 first=first",
            "[0] must be the document-order first match"
        );
    }

    /// And the full sequence must be in document order.
    #[test]
    fn by_class_sequence_is_document_order() {
        let out = run(r#"
            var c = document.getElementsByClassName('k');
            var seq = [];
            for (var i = 0; i < c.length; i++) { seq.push(c[i].id); }
            document.getElementById('out').setText(seq.join(','));
            "#);
        assert_eq!(
            out, "first,mid,last",
            "the collection must be in document order"
        );
    }

    /// Same for `getElementsByTagName`.
    #[test]
    fn by_tag_sequence_is_document_order() {
        let out = run(r#"
            var c = document.getElementsByTagName('div');
            var seq = [];
            for (var i = 0; i < c.length; i++) {
                if (c[i].id) { seq.push(c[i].id); }
            }
            document.getElementById('out').setText(seq.join(','));
            "#);
        // #out is also a <div> and sits after #last in document order — its
        // presence is CORRECT document ordering, not a regression.
        assert_eq!(
            out, "first,mid,last,out",
            "the by-tag collection must be in document order"
        );
    }

    /// querySelector takes the FIRST match in tree order.
    #[test]
    fn query_selector_returns_the_first_match() {
        let out = run(r#"
            var el = document.querySelector('.k');
            document.getElementById('out').setText('id=' + el.id);
            "#);
        assert_eq!(out, "id=first", "querySelector must take the first match");
    }

    /// Determinism across repeated lookups: every read returns the same order.
    #[test]
    fn repeated_lookups_are_stable() {
        let out = run(r#"
            var s1 = [];
            var c1 = document.getElementsByClassName('k');
            for (var i = 0; i < c1.length; i++) { s1.push(c1[i].id); }
            var s2 = [];
            var c2 = document.getElementsByClassName('k');
            for (var i = 0; i < c2.length; i++) { s2.push(c2[i].id); }
            document.getElementById('out').setText(
                (s1.join(',') === s2.join(',')) + '|' + s1.join(',')
            );
            "#);
        assert_eq!(
            out, "true|first,mid,last",
            "repeated lookups must be stable"
        );
    }
}

#[cfg(test)]
mod collection_uniform_order_tests {
    //! Round-2 S1/S2 of PR #107: the `*` path flattened query_by_tag's
    //! per-key lists (HashMap order — grouped by tag, not document order),
    //! the document-level multi-token class query used the whole string as
    //! one token (always empty), and 3 of 5 changed paths had no
    //! discriminating test. Everything now filters the ONE tree-order
    //! `all_element_ids` sequence, and these tests pin each shape.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body>
            <div id="host">
              <a id="a1">a1</a>
              <div id="mid"><b id="b1">b1</b><a id="a2">a2</a></div>
              <b id="bb">bb</b>
            </div>
            <div id="out">i</div>
            </body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// `getElementsByTagName('*')` must return ALL elements in DOCUMENT
    /// order (pre-order: a1, mid, b1, a2, bb, host, out...). Round-2 S1: the
    /// old `*` path flattened query_by_tag's per-key lists and grouped by
    /// tag in HashMap order.
    #[test]
    fn star_collection_is_document_ordered() {
        let out = run(r#"
            var c = document.getElementsByTagName('*');
            var ids = [];
            for (var i = 0; i < c.length; i++) { if (c[i].id) ids.push(c[i].id); }
            document.getElementById('out').setText(ids.join(','));
            "#);
        assert_eq!(
            out, "host,a1,mid,b1,a2,bb,out",
            "the star collection must be in document (pre-)order"
        );
    }

    /// Same shape through an ELEMENT handle, scoped to its descendants:
    /// host.getElementsByTagName('*') = descendants of host in order.
    #[test]
    fn element_star_collection_is_document_ordered_and_scoped() {
        let out = run(r#"
            var host = document.getElementById('host');
            var c = host.getElementsByTagName('*');
            var ids = [];
            for (var i = 0; i < c.length; i++) { if (c[i].id) ids.push(c[i].id); }
            document.getElementById('out').setText(ids.join(','));
            "#);
        assert_eq!(
            out, "a1,mid,b1,a2,bb",
            "element-scoped star: host's descendants in order, host/out excluded"
        );
    }

    /// Document-level MULTI-TOKEN class query: 'a b' must match elements
    /// carrying both tokens (round-2 S2: the whole string was used as one
    /// token and the query always returned empty).
    #[test]
    fn document_multi_token_class_query_matches() {
        let out = run(r#"
            var host = document.getElementById('host');
            host.setAttribute('class', 'x y');
            var c = document.getElementsByClassName('x y');
            var n = c.length;
            var hasHost = false;
            for (var i = 0; i < c.length; i++) { if (c[i].id === 'host') hasHost = true; }
            document.getElementById('out').setText('n=' + n + ' hasHost=' + hasHost);
            "#);
        assert_eq!(
            out, "n=1 hasHost=true",
            "a multi-token class query must match elements carrying both tokens"
        );
    }
}

#[cfg(test)]
mod query_selector_live_tests {
    //! PR #107 R3 S3: `querySelector('.cls')` read the frozen per-key index,
    //! so a same-run `setAttribute('class', ...)` (now reflected into
    //! `node_props.class_name` by the set_attr cobweb) was invisible to
    //! `querySelector` while `getElementsByClassName` saw it. querySelector
    //! now scans the same tree-order element list the collections use.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="el">E</div><span id="sp">S</span>
            <em class="parsecls">P</em><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// The reported shape: same-run setAttribute then querySelector.
    #[test]
    fn query_selector_sees_a_same_run_class_write() {
        let out = run(r#"
            var el = document.getElementById('el');
            el.setAttribute('class', 'fresh');
            var q = document.querySelector('.fresh');
            document.getElementById('out').setText(
                'found=' + (q !== null) + ' same=' + (q === el)
            );
            "#);
        assert_eq!(
            out, "found=true same=true",
            "querySelector must see a same-run class write"
        );
    }

    /// Semantic invariants: #id, .cls and tag forms still resolve parsed
    /// elements, and no-match returns null.
    #[test]
    fn selector_forms_still_resolve() {
        // Round-2 S3-c: assert IDENTITY against getElementById (non-null
        // would pass even if the tag arm returned the LAST div).
        let out = run(r#"
            var d1 = document.querySelector('div');
            var d1u = document.querySelector('DIV');
            var d1ref = document.getElementById('el');
            var sp = document.querySelector('span');
            var n1 = document.querySelector('#el');
            var c1 = document.querySelector('.parsecls');
            var emref = document.querySelector('em');
            var nope = document.querySelector('nosuchtag');
            var r = [];
            r.push('d1=' + (d1 === d1ref) + '/' + (d1 && d1.textContent));
            r.push('d1u=' + (d1u === d1ref));
            r.push('sp=' + (sp && sp.id));
            r.push('n1=' + (n1 === d1ref));
            r.push('c1=' + (c1 === emref) + '/' + (c1 && c1.tagName));
            r.push('nope=' + (nope === null));
            document.getElementById('out').setText(r.join(' '));
            "#);
        assert_eq!(
            out, "d1=true/E d1u=true sp=sp n1=true c1=true/EM nope=true",
            "tag/.cls/#id forms must resolve by identity across spellings"
        );
    }
}

#[cfg(test)]
mod id_attr_cobweb_tests {
    //! Round-2 of PR #108: `setAttribute('id', ...)` did not update
    //! `node_props.id` (the set_attr cobweb only updated the JS `id`
    //! property), so both `getElementById('newid')` and
    //! `querySelector('#newid')` were blind to a same-run id write while
    //! `getElementById('oldid')` still returned the element. The set_attr
    //! cobweb now writes `node_props.id`, and both lookups fall back to a
    //! live `node_props` scan when their bind-time maps miss.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="el">E</div><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// The reported shape: setAttribute('id','newid') then BOTH lookups by
    /// the new id must find the element.
    #[test]
    fn same_run_id_write_is_visible_to_both_lookups() {
        let out = run(r#"
            var el = document.getElementById('el');
            el.setAttribute('id', 'newid');
            var byQs = document.querySelector('#newid');
            var byId = document.getElementById('newid');
            document.getElementById('out').setText(
                'qs=' + (byQs === el) + ' gid=' + (byId === el)
            );
            "#);
        assert_eq!(
            out, "qs=true gid=true",
            "both id lookups must see a same-run setAttribute id write"
        );
    }

    /// The OLD id must stop resolving after the attribute moved.
    #[test]
    fn old_id_stops_resolving_after_the_write() {
        let out = run(r#"
            var el = document.getElementById('el');
            el.setAttribute('id', 'newid');
            var old = document.getElementById('el');
            var qold = document.querySelector('#el');
            document.getElementById('out').setText(
                'old=' + (old !== null) + ' qold=' + (qold !== null)
            );
            "#);
        assert_eq!(
            out, "old=false qold=false",
            "the old id must stop resolving once the attribute moved"
        );
    }
}

#[cfg(test)]
mod remove_attribute_id_tests {
    //! The mirror image of PR #109: `removeAttribute('id')` left the `ids` /
    //! `query_by_id` index entries in place, so BOTH lookups kept returning
    //! the element after its id attribute was gone (ghost resolution).

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="el">E</div><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// The reported shape: removeAttribute('id') then BOTH lookups by the
    /// removed id must return null.
    #[test]
    fn removed_id_stops_resolving_everywhere() {
        let out = run(r#"
            var el = document.getElementById('el');
            el.removeAttribute('id');
            var byId = document.getElementById('el');
            var byQs = document.querySelector('#el');
            document.getElementById('out').setText(
                'byId=' + (byId !== null) + ' byQs=' + (byQs !== null)
            );
            "#);
        assert_eq!(
            out, "byId=false byQs=false",
            "a removed id must stop resolving through both lookups"
        );
    }

    /// The guard must not over-remove: removing ANOTHER attribute must not
    /// disturb the id index.
    #[test]
    fn removing_another_attribute_keeps_the_id_resolvable() {
        let out = run(r#"
            var el = document.getElementById('el');
            el.setAttribute('data-x', '1');
            el.removeAttribute('data-x');
            var byId = document.getElementById('el');
            document.getElementById('out').setText('byId=' + (byId !== null));
            "#);
        assert_eq!(
            out, "byId=true",
            "removing an unrelated attribute must not clear the id index"
        );
    }

    /// Re-adding the id after removal must make it resolvable again.
    #[test]
    fn id_can_be_readded_after_removal() {
        let out = run(r#"
            var el = document.getElementById('el');
            el.removeAttribute('id');
            el.setAttribute('id', 'el');
            var byId = document.getElementById('el');
            document.getElementById('out').setText('byId=' + (byId !== null));
            "#);
        assert_eq!(out, "byId=true", "re-adding the id must restore lookups");
    }
}

#[cfg(test)]
mod stop_propagation_tests {
    //! stopPropagation / stopImmediatePropagation were NO-OP stubs — calling
    //! them did nothing, so a listener could not stop dispatch.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="el">E</div><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// DOM: stopImmediatePropagation halts everything after the listener that
    /// called it — a second listener on the SAME element must not fire.
    #[test]
    fn stop_immediate_halts_remaining_same_element_listeners() {
        let out = run(r#"
            var log = [];
            var t = new EventTarget();
            t.addEventListener('ping', function () { log.push('A'); });
            t.addEventListener('ping', function (e) {
                log.push('B');
                e.stopImmediatePropagation();
            });
            t.addEventListener('ping', function () { log.push('C'); });
            // A real Event instance (not a plain object — a plain `{type}`
            // object has no stop methods, so the handler could not stop).
            t.dispatchEvent(new Event('ping'));
            document.getElementById('out').setText(log.join(''));
            "#);
        assert_eq!(
            out, "AB",
            "stopImmediatePropagation must halt the remaining listeners"
        );
    }

    /// DOM: stopPropagation does NOT stop same-target listeners — the `.cls`
    /// sibling test pins the distinction (immediate stops, propagation does
    /// not). Here via the element dispatch surface.
    #[test]
    fn stop_propagation_does_not_stop_same_element_listeners() {
        let out = run(r#"
            var log = [];
            var el = document.getElementById('el');
            el.addEventListener('ping', function (e) {
                log.push('A');
                e.stopPropagation();
            });
            el.addEventListener('ping', function () { log.push('B'); });
            el.dispatchEvent({ type: 'ping' });
            document.getElementById('out').setText(log.join(''));
            "#);
        assert_eq!(
            out, "AB",
            "stopPropagation must NOT halt same-target listeners (DOM)"
        );
    }

    /// The fire_click path: a click handler calling stopPropagation stops
    /// the document-level walk — a document click listener must NOT fire.
    #[test]
    fn fire_click_stop_propagation_halts_document_walk() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body>
            <div id="btn">B</div><div id="out">i</div>
            </body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var btn = document.getElementById('btn');
            btn.addEventListener('click', function (e) { e.stopPropagation(); });
            document.addEventListener('click', function () {
                document.getElementById('out').setText('DOC-FIRED');
            });
            "#,
        );
        let btn_id = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("btn"))
            .map(|(i, _)| i.as_u64())
            .expect("missing #btn");
        rt.fire_click(&mut doc, btn_id);
        // The document listener must NOT have fired (no DOC-FIRED text), and
        // the click event object reached the handler without a stop flag.
        assert_eq!(
            out_of(&doc),
            "i",
            "stopPropagation must halt the document-level click walk"
        );
    }

    /// Round-3 S3: the stop flags are dispatch-scoped — REUSING one Event
    /// object across two dispatches must start the second dispatch clean
    /// (WHATWG resets the flags at dispatch start).
    #[test]
    fn reused_event_object_starts_each_dispatch_clean() {
        let out = run(r#"
            var log = [];
            var t = new EventTarget();
            t.addEventListener('ping', function () { log.push('1'); });
            t.addEventListener('ping', function (e) {
                log.push('S');
                e.stopImmediatePropagation();
            });
            var ev = new Event('ping');
            t.dispatchEvent(ev);
            // second dispatch with the SAME (stopped) object
            t.dispatchEvent(ev);
            document.getElementById('out').setText(log.join(''));
            "#);
        assert_eq!(
            out, "1S1S",
            "a reused Event object must start each dispatch with clean flags"
        );
    }

    /// Round-4 S3: the ELEMENT dispatch clear (the flat block inside
    /// `make_element_handle`'s `dispatchEvent`, ~14541) is pinned separately
    /// — the EventTarget-path test (`new EventTarget()`, block ~3279) cannot
    /// see it. Each of the three clear blocks has exactly one test.
    #[test]
    fn element_dispatch_reused_event_starts_clean() {
        let out = run(r#"
            var log = [];
            var el = document.getElementById('el');
            el.addEventListener('ping', function () { log.push('E1'); });
            el.addEventListener('ping', function (e) {
                log.push('S');
                e.stopImmediatePropagation();
            });
            el.addEventListener('ping', function () { log.push('E2'); });
            var ev = new Event('ping');
            el.dispatchEvent(ev);
            el.dispatchEvent(ev);
            document.getElementById('out').setText(log.join(''));
            "#);
        assert_eq!(
            out, "E1SE1S",
            "element dispatch must reset the flags per dispatch"
        );
    }

    /// Round-4 S3: the DOCUMENT dispatch clear (the indented block in the
    /// document's `disp_ev`, ~12282) is pinned separately.
    #[test]
    fn document_dispatch_reused_event_starts_clean() {
        let out = run(r#"
            var log = [];
            document.addEventListener('ping', function () { log.push('D1'); });
            document.addEventListener('ping', function (e) {
                log.push('S');
                e.stopImmediatePropagation();
            });
            var ev = new Event('ping');
            document.dispatchEvent(ev);
            document.dispatchEvent(ev);
            document.getElementById('out').setText(log.join(''));
            "#);
        assert_eq!(
            out, "D1SD1S",
            "document dispatch must reset the flags per dispatch"
        );
    }

    /// Control: WITHOUT stopPropagation the document listener fires.
    #[test]
    fn fire_click_without_stop_propagation_reaches_document() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body>
            <div id="btn">B</div><div id="out">i</div>
            </body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var btn = document.getElementById('btn');
            btn.addEventListener('click', function () {
                document.getElementById('out').setText('DOC-FIRED');
            });
            "#,
        );
        let btn_id = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("btn"))
            .map(|(i, _)| i.as_u64())
            .expect("missing #btn");
        rt.fire_click(&mut doc, btn_id);
        assert_eq!(
            out_of(&doc),
            "DOC-FIRED",
            "control: the document walk must run without stopPropagation"
        );
    }
}

#[cfg(test)]
mod stop_propagation_ancestor_tests {
    //! Round-2 S0/S1/S2 of PR #111: (S0) stopImmediatePropagation from an
    //! ANCESTOR did not halt the document walk; (S1) document listeners
    //! received no event; (S2) CustomEvent instances carried no-op stop
    //! methods.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body>
            <div id="host"><div id="anc">A</div><div id="btn">B</div></div>
            <div id="out">i</div>
            </body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// S0: stopImmediatePropagation from an ANCESTOR (#host) halts the
    /// document walk — a document click listener must NOT fire.
    #[test]
    fn ancestor_stop_immediate_halts_document_walk() {
        let mut doc = HtmlDocument::from_html(
            // #btn nested INSIDE #host: the ancestor walk must pass through
            // #host for the propagation-stop to be observable.
            r#"<html><body>
            <div id="host"><div id="btn">B</div></div><div id="out">i</div>
            </body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var host = document.getElementById('host');
            host.addEventListener('click', function (e) {
                e.stopImmediatePropagation();
            });
            document.addEventListener('click', function () {
                document.getElementById('out').setText('DOC');
            });
            "#,
        );
        let btn_nid = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("btn"))
            .map(|(i, _)| i.as_u64())
            .expect("missing #btn");
        rt.fire_click(&mut doc, btn_nid);
        assert_eq!(
            out_of(&doc),
            "i",
            "ancestor stopImmediate must halt the document walk"
        );
    }

    /// S1: document listeners RECEIVE the event object.
    #[test]
    fn document_listener_receives_the_event() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            document.addEventListener('click', function (e) {
                document.getElementById('out').setText('type=' + e.type);
            });
            "#,
        );
        let out_nid = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| i.as_u64())
            .expect("missing #out");
        rt.fire_click(&mut doc, out_nid);
        assert_eq!(
            out_of(&doc),
            "type=click",
            "document listeners get the event"
        );
    }

    /// S2: a CustomEvent's stopImmediatePropagation halts dispatch.
    #[test]
    fn custom_event_stop_immediate_halts() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var log = [];
            var t = new EventTarget();
            t.addEventListener('ce', function (e) {
                log.push('A');
                e.stopImmediatePropagation();
            });
            t.addEventListener('ce', function () { log.push('B'); });
            t.dispatchEvent(new CustomEvent('ce'));
            document.getElementById('out').setText(log.join(''));
            "#,
        );
        assert_eq!(
            out_of(&doc),
            "A",
            "CustomEvent stopImmediate must halt remaining listeners"
        );
    }

    /// S0 control: WITHOUT the stop, the document listener fires.
    #[test]
    fn ancestor_without_stop_document_walk_runs() {
        let mut doc = HtmlDocument::from_html(
            // #btn nested INSIDE #host: the ancestor walk must pass through
            // #host for the propagation-stop to be observable.
            r#"<html><body>
            <div id="host"><div id="btn">B</div></div><div id="out">i</div>
            </body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var host = document.getElementById('host');
            host.addEventListener('click', function () { /* no stop */ });
            document.addEventListener('click', function () {
                document.getElementById('out').setText('DOC');
            });
            "#,
        );
        let btn_nid = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("btn"))
            .map(|(i, _)| i.as_u64())
            .expect("missing #btn");
        rt.fire_click(&mut doc, btn_nid);
        assert_eq!(out_of(&doc), "DOC", "control: document walk runs");
    }
}

#[cfg(test)]
mod event_object_polish_tests {
    //! PR #111 residuals: the fire_click event carried no target /
    //! currentTarget / preventDefault, and CustomEvent stored the raw init
    //! dict as `detail`.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    /// The fire_click event carries target/currentTarget (the click target)
    /// and a working preventDefault.
    #[test]
    fn fire_click_event_has_target_and_prevent_default() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="btn">B</div><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var btn = document.getElementById('btn');
            btn.addEventListener('click', function (e) {
                document.getElementById('out').setText(
                    'type=' + e.type +
                    ' tgt=' + (e.target && e.target.id) +
                    ' cur=' + (e.currentTarget && e.currentTarget.id) +
                    ' pd=' + (typeof e.preventDefault) +
                    ' dp=' + e.defaultPrevented
                );
            });
            "#,
        );
        let btn_nid = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("btn"))
            .map(|(i, _)| i.as_u64())
            .expect("missing #btn");
        rt.fire_click(&mut doc, btn_nid);
        assert_eq!(
            out_of(&doc),
            "type=click tgt=btn cur=btn pd=function dp=false",
            "the click event must carry target/currentTarget/preventDefault"
        );
    }

    /// Round-2 S2/S3: (a) e.target is the STABLE handle (=== the prefetched
    /// getElementById handle); (b) currentTarget is the node WHOSE listener
    /// runs — the ancestor handler sees the ancestor, the document handler
    /// sees document (a static copy of the click target lied to both).
    #[test]
    fn fire_click_current_target_tracks_the_listening_node() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body>
            <div id="host"><div id="btn">B</div></div><div id="out">i</div>
            </body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var btn = document.getElementById('btn');
            var log = [];
            btn.addEventListener('click', function (e) {
                log.push('btn:tgt===' + (e.target === btn) +
                    ' cur=btn:' + (e.currentTarget === btn));
            });
            var host = document.getElementById('host');
            host.addEventListener('click', function (e) {
                log.push('host:cur=host:' + (e.currentTarget === host) +
                    ' tgt=btn:' + (e.target === btn));
            });
            document.addEventListener('click', function (e) {
                log.push('doc:cur=doc:' + (e.currentTarget === document));
                // fire_click runs AFTER the script, so the last handler
                // publishes the collected log.
                document.getElementById('out').setText(log.join(' '));
            });
            "#,
        );
        let btn_nid = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("btn"))
            .map(|(i, _)| i.as_u64())
            .expect("missing #btn");
        rt.fire_click(&mut doc, btn_nid);
        assert_eq!(
            out_of(&doc),
            "btn:tgt===true cur=btn:true host:cur=host:true tgt=btn:true doc:cur=doc:true",
            "currentTarget must track the listening node; target must be the stable handle"
        );
    }

    /// Round-3 S1: currentTarget must be null AFTER dispatch completes —
    /// a held event read from a LATER dispatch sees null (the previous
    /// reset sat before the document walk, so the event kept pointing at
    /// the document).
    #[test]
    fn held_event_reads_null_current_target_after_dispatch() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="btn">B</div><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var btn = document.getElementById('btn');
            var out = document.getElementById('out');
            document.addEventListener('click', function (e) {
                if (window.__ev) {
                    out.setText('post=' + (window.__ev.currentTarget === null));
                }
                window.__ev = e;
            });
            "#,
        );
        let btn_nid = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("btn"))
            .map(|(i, _)| i.as_u64())
            .expect("missing #btn");
        // Click 1 holds the event; click 2 reads click 1's post-dispatch state.
        rt.fire_click(&mut doc, btn_nid);
        rt.fire_click(&mut doc, btn_nid);
        assert_eq!(
            out_of(&doc),
            "post=true",
            "a held event must read null currentTarget after its dispatch completed"
        );
    }

    /// preventDefault flips defaultPrevented on the event.
    #[test]
    fn fire_click_prevent_default_sets_the_flag() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="btn">B</div><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var btn = document.getElementById('btn');
            btn.addEventListener('click', function (e) {
                e.preventDefault();
                document.getElementById('out').setText('dp=' + e.defaultPrevented);
            });
            "#,
        );
        let btn_nid = doc
            .tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("btn"))
            .map(|(i, _)| i.as_u64())
            .expect("missing #btn");
        rt.fire_click(&mut doc, btn_nid);
        assert_eq!(
            out_of(&doc),
            "dp=true",
            "preventDefault must flip defaultPrevented"
        );
    }

    /// CustomEvent detail unwraps the init dict's `detail` member.
    #[test]
    fn custom_event_detail_unwraps_the_init_dict() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var log = [];
            var t = new EventTarget();
            t.addEventListener('ce', function (e) {
                log.push('d=' + e.detail);
            });
            t.addEventListener('ce2', function (e) {
                log.push('d2=' + e.detail);
            });
            t.dispatchEvent(new CustomEvent('ce', { detail: 42 }));
            t.dispatchEvent(new CustomEvent('ce2'));
            document.getElementById('out').setText(log.join(' '));
            "#,
        );
        assert_eq!(
            out_of(&doc),
            "d=42 d2=null",
            "detail must unwrap the init dict; absent detail is null"
        );
    }
}

#[cfg(test)]
mod style_cache_hardening_tests {
    //! The `_arisCssTextCache` property was writable+configurable, so a page
    //! could poison it (`el.style._arisCssTextCache = 'garbage'`) and the
    //! next `cssText` read returned the garbage verbatim. The cache is now
    //! non-writable / non-configurable: runtime writes go through
    //! `insert_property` (internal channel) and still work; page scribbles
    //! are no-ops (sloppy mode).

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body style="color:red"><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// The reported shape: scribble the cache, read cssText.
    #[test]
    fn scribbling_the_cache_does_not_poison_csstext() {
        let out = run(r#"
            var r = [];
            var el = document.body;
            r.push('seeded=' + el.style.cssText);
            el.style._arisCssTextCache = 'garbage';
            r.push('after=' + el.style.cssText);
            el.style.cssText = 'color:blue';
            r.push('rewrite=' + el.style.cssText);
            document.getElementById('out').setText(r.join(' '));
            "#);
        assert_eq!(
            out, "seeded=color:red after=color:red rewrite=color:blue",
            "a page scribble must not poison cssText; runtime writes still work"
        );
    }

    /// removeAttribute('style') clears the cache to empty and the setter
    /// Round-2 S1: the SETTER and REMOVEATTRIBUTE lockdown flags are pinned
    /// here via descriptor assertions — the scribble test only exercises the
    /// seeded site, so reverting either of the other two left the whole
    /// suite green (R2's mutations M2/M3 survived).
    #[test]
    fn setter_and_remove_attribute_lockdown_is_pinned() {
        let out = run(r#"
            var r = [];
            var el = document.body;
            // After a cssText SETTER write the cache must still be locked.
            el.style.cssText = 'color:blue';
            var d1 = Object.getOwnPropertyDescriptor(el.style, '_arisCssTextCache');
            r.push('setterW=' + d1.writable + ' setterC=' + d1.configurable);
            // After removeAttribute the reinstalled cache must still be locked.
            el.removeAttribute('style');
            var d2 = Object.getOwnPropertyDescriptor(el.style, '_arisCssTextCache');
            r.push('rmW=' + (d2 === undefined ? 'absent' : d2.writable) +
                ' rmC=' + (d2 === undefined ? 'absent' : d2.configurable));
            el.style.cssText = 'color:green';
            var d3 = Object.getOwnPropertyDescriptor(el.style, '_arisCssTextCache');
            r.push('reW=' + d3.writable + ' reC=' + d3.configurable);
            document.getElementById('out').setText(r.join(' '));
            "#);
        assert_eq!(
            out, "setterW=false setterC=false rmW=false rmC=false reW=false reC=false",
            "the setter and removeAttribute cache installs must stay locked"
        );
    }
}

#[cfg(test)]
mod event_api_surface_tests {
    //! L940 event-API family, probed 2026-11-28 (PR #114): the recorded
    //! ghost-fire S2 (`remove; dispatch` firing once) is ALREADY FIXED by the
    //! WHATWG dedup work — one shape pinned here; R2 probes verified the
    //! other two (refetch, double-add) plus a positive control. Two REAL
    //! gaps fixed
    //! here: `instanceof Event` THREW ("function has non-object prototype")
    //! and `window.addEventListener` was undefined (window-level listeners
    //! silently no-op'd).

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="el">E</div><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// Recorded ghost-fire S2 (PR #94 handoff): `remove; dispatch` fired
    /// once. Already fixed by the dedup work — pinned here so it stays fixed.
    #[test]
    fn remove_then_dispatch_does_not_ghost_fire() {
        let out = run(r#"
            var log = [];
            var el = document.getElementById('el');
            var fn = function () { log.push('X'); };
            el.addEventListener('ping', fn);
            el.removeEventListener('ping', fn);
            el.dispatchEvent({ type: 'ping' });
            document.getElementById('out').setText('len=' + log.length);
            "#);
        assert_eq!(out, "len=0", "remove-then-dispatch must not ghost-fire");
    }

    /// instanceof Event works (was: threw "function has non-object
    /// prototype in instanceof check").
    #[test]
    fn instance_of_event_works() {
        let out = run(r#"
            var r = [];
            var ev = new Event('x');
            r.push('ev=' + (ev instanceof Event));
            var ce = new CustomEvent('ce');
            r.push('ce=' + (ce instanceof CustomEvent));
            r.push('ceEv=' + (ce instanceof Event));
            document.getElementById('out').setText(r.join(' '));
            "#);
        assert_eq!(
            out, "ev=true ce=true ceEv=true",
            "instanceof Event/CustomEvent must work (CustomEvent chains to Event)"
        );
    }

    /// window.addEventListener delegates to the document surface — a
    /// window-level listener fires (was: undefined, silent no-op).
    #[test]
    fn window_add_listener_fires() {
        let out = run(r#"
            var log = [];
            var err = '';
            try {
                window.addEventListener('ping', function () { log.push('W'); });
                window.dispatchEvent({ type: 'ping' });
            } catch (e) { err = 'threw:' + e.message; }
            var r = [];
            r.push('typeof=' + (typeof window.addEventListener));
            r.push('fired=' + (log.length === 1));
            r.push(err);
            document.getElementById('out').setText(r.join(' '));
            "#);
        assert_eq!(
            out, "typeof=function fired=true ",
            "window.addEventListener must exist and fire via document dispatch"
        );
    }

    /// window.removeEventListener removes (the delegated contract).
    #[test]
    fn window_remove_listener_stops_firing() {
        let out = run(r#"
            var log = [];
            var fn = function () { log.push('W'); };
            var err = '';
            try {
                window.addEventListener('ping', fn);
                window.removeEventListener('ping', fn);
                window.dispatchEvent({ type: 'ping' });
            } catch (e) { err = 'threw:' + e.message; }
            document.getElementById('out').setText('len=' + log.length + ' ' + err);
            "#);
        assert_eq!(out, "len=0 ", "window.removeEventListener must remove");
    }
}

#[cfg(test)]
mod eventtarget_instanceof_tests {
    //! `new EventTarget() instanceof EventTarget` THREW "function has
    //! non-object prototype in instanceof check" — register_global_callable
    //! does not create a `.prototype` object. EventTarget.prototype now
    //! exists (with the constructor back-reference) and minted targets use it
    //! as [[Prototype]].

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    #[test]
    fn eventtarget_instanceof_and_prototype() {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(
            &mut doc,
            r#"
            var r = [];
            r.push('et=' + (new EventTarget() instanceof EventTarget));
            r.push('proto=' + (typeof EventTarget.prototype));
            r.push('ctor=' + (EventTarget.prototype.constructor === EventTarget));
            // Non-permissive: a plain object and an Event are NOT EventTargets.
            r.push('plain=' + (({}) instanceof EventTarget));
            r.push('ev=' + (new Event('x') instanceof EventTarget));
            // An EventTarget still dispatches after the prototype change.
            var log = [];
            var t = new EventTarget();
            t.addEventListener('old', function () { log.push('O'); });
            t.dispatchEvent(new Event('old'));
            r.push('dispatched=' + (log.length === 1));
            // KNOWN LIMIT (round-2 S2, pinned so it is documented rather than
            // silent): the methods are OWN properties of each minted target,
            // not on the prototype — so `Object.create(EventTarget.prototype)`
            // is instanceof-correct but has no addEventListener (the canonical
            // polyfill idiom does not work). Moving them to the prototype is a
            // separate refactor.
            var derived = Object.create(EventTarget.prototype);
            r.push('derivedIsof=' + (derived instanceof EventTarget));
            r.push('protoMth=' + (typeof EventTarget.prototype.addEventListener));
            // ECMA-262: prototype.constructor is CONFIGURABLE.
            var cd = Object.getOwnPropertyDescriptor(EventTarget.prototype, 'constructor');
            r.push('ctorCfg=' + cd.configurable);
            // FAMILY CONSISTENCY (round-5 S3): Event / CustomEvent /
            // EventTarget must agree on the `prototype` descriptor —
            // PR #114 wrote writable(true) for Event/CustomEvent while
            // EventTarget is spec-correct writable(false). Three-way pinned.
            var pw = function (C) {
                return Object.getOwnPropertyDescriptor(C, 'prototype').writable;
            };
            r.push('pw=' + pw(Event) + '/' + pw(CustomEvent) + '/' + pw(EventTarget));
            document.getElementById('out').setText(r.join(' '));
        "#,
        );
        assert_eq!(
            out_of(&doc),
            "et=true proto=object ctor=true plain=false ev=false dispatched=true \
             derivedIsof=true protoMth=undefined ctorCfg=true pw=false/false/false",
            "EventTarget instanceof must work and stay non-permissive"
        );
    }
}

#[cfg(test)]
mod element_prototype_tests {
    //! Element `instanceof` was completely broken: `register_global_callable`
    //! creates no `.prototype`, so every interface constructor
    //! (Node/Element/HTMLElement/HTML*Element/Document) had none and the
    //! checks THREW ("function has non-object prototype in instanceof
    //! check"). Fixing only the constructors was not enough — the lookups
    //! (getElementById, collections) mint handles through
    //! cached_element_handle, which never called set_element_prototype — and
    //! the chain was missing the HTML*Element -> HTMLElement links plus the
    //! EventTarget root.

    use super::JsRuntime;
    use blitz_dom::DocumentConfig;
    use blitz_html::HtmlDocument;

    fn out_of(doc: &HtmlDocument) -> String {
        doc.tree()
            .iter()
            .find(|(_, n)| n.attr(blitz_dom::local_name!("id")) == Some("out"))
            .map(|(i, _)| doc.get_node(i).map(|n| n.text_content()))
            .unwrap_or_default()
            .unwrap_or_default()
    }

    fn run(script: &str) -> String {
        let mut doc = HtmlDocument::from_html(
            r#"<html><body><div id="d">D</div><span id="s">S</span><div id="out">i</div></body></html>"#,
            DocumentConfig::default(),
        );
        let mut rt = JsRuntime::new();
        rt.bind_and_run(&mut doc, script);
        out_of(&doc)
    }

    /// The element-class chain, by identity, through getElementById.
    #[test]
    fn element_instanceof_chain_works() {
        let out = run(r#"
            var d = document.getElementById('d');
            var r = [];
            r.push('div=' + (d instanceof HTMLDivElement));
            r.push('html=' + (d instanceof HTMLElement));
            r.push('elem=' + (d instanceof Element));
            r.push('node=' + (d instanceof Node));
            // Real DOM: EventTarget is the root of the node inheritance chain.
            r.push('et=' + (d instanceof EventTarget));
            // Non-permissive: a <span> is NOT an HTMLDivElement.
            r.push('span=' + (document.getElementById('s') instanceof HTMLDivElement));
            r.push('plain=' + (({}) instanceof Node));
            r.push('protoT=' + (typeof HTMLElement.prototype));
            r.push('ctorBR=' + (HTMLElement.prototype.constructor === HTMLElement));
            // Round-2 S2 #2: the document global itself must be a Node AND a
            // Document (its prototype used to never be set).
            r.push('docNode=' + (document instanceof Node));
            r.push('docDoc=' + (document instanceof Document));
            r.push('docElem=' + (document instanceof Element));
            // Round-2 S2 #1: `constructor` on the new prototypes must be
            // non-enumerable (for..in must not leak it).
            var cd = Object.getOwnPropertyDescriptor(HTMLElement.prototype, 'constructor');
            r.push('ctorE=' + (cd && cd.enumerable === false));
            var ctorLeaks = [];
            for (var k in HTMLElement.prototype) { if (k === 'constructor') ctorLeaks.push(k); }
            r.push('ctorLeak=' + ctorLeaks.length);
            document.getElementById('out').setText(r.join(' '));
        "#);
        assert_eq!(
            out,
            "div=true html=true elem=true node=true et=true \
             span=false plain=false protoT=object ctorBR=true \
             docNode=true docDoc=true docElem=false ctorE=true ctorLeak=0",
            "the element prototype chain must resolve by identity, include the \
             document, and not leak constructor"
        );
    }
}
